/**
 * Prepares a release on a branch from an up-to-date `main`: sets the new version in
 * app/package.json and adds its section to CHANGELOG.md, generated by git-cliff from the
 * Conventional Commits since the last release tag. A maintainer curates the section and
 * merges the result as `chore(release): v<version>`; the release workflow does the rest.
 *
 * Usage: pnpm release:prepare <patch|minor|major|beta|X.Y.Z[-beta.N]>
 *
 * - `beta` continues a prerelease (`0.2.0-beta.1` → `0.2.0-beta.2`) or starts the first
 *   beta of the next minor version (`0.1.0` → `0.2.0-beta.1`).
 * - `patch`, `minor` and `major` bump that part; from a prerelease they finish it when it
 *   already has that form (`0.2.0-beta.3` with `minor` → `0.2.0`).
 */
import { spawnSync } from 'node:child_process';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { compareVersions } from './releases.ts';

const root = resolve(import.meta.dirname, '../..');
const packageFile = resolve(root, 'app/package.json');
const changelogFile = resolve(root, 'CHANGELOG.md');
const changelogHeader = `# Changelog

All notable changes are listed here, newest first. Versions follow [Semantic Versioning](https://semver.org); prereleases (\`-beta.N\`) are published on the beta channel.
`;

/**
 * The version that follows `current` for a bump kind or an explicit version.
 * @param current - Current version, `X.Y.Z` or `X.Y.Z-beta.N`.
 * @param bump - `patch`, `minor`, `major`, `beta` or an explicit version.
 */
function nextVersion(current: string, bump: string): string {
  const match = /^(\d+)\.(\d+)\.(\d+)(?:-beta\.(\d+))?$/.exec(current);
  if (match === null) throw new Error(`Unexpected current version ${current}`);
  const [major, minor, patch] = [match[1], match[2], match[3]].map(Number) as [
    number,
    number,
    number,
  ];
  const beta = match[4] === undefined ? undefined : Number(match[4]);
  let next: string;
  if (bump === 'beta') {
    next =
      beta === undefined ? `${major}.${minor + 1}.0-beta.1` : `${major}.${minor}.${patch}-beta.${beta + 1}`;
  } else if (bump === 'patch') {
    next = beta === undefined ? `${major}.${minor}.${patch + 1}` : `${major}.${minor}.${patch}`;
  } else if (bump === 'minor') {
    next = beta !== undefined && patch === 0 ? `${major}.${minor}.0` : `${major}.${minor + 1}.0`;
  } else if (bump === 'major') {
    next =
      beta !== undefined && minor === 0 && patch === 0 ? `${major}.0.0` : `${major + 1}.0.0`;
  } else if (/^\d+\.\d+\.\d+(-beta\.\d+)?$/.test(bump)) {
    next = bump;
  } else {
    throw new Error(`Unknown bump ${bump}: use patch, minor, major, beta or a version`);
  }
  if (compareVersions(next, current) <= 0) throw new Error(`${next} is not newer than ${current}`);
  return next;
}

function run(command: string, args: readonly string[]): string {
  const result = spawnSync(command, args, { cwd: root, encoding: 'utf8' });
  if (result.status !== 0) throw new Error(`${command} ${args.join(' ')} failed: ${result.stderr}`);
  return result.stdout;
}

function main(bump: string | undefined): void {
  if (bump === undefined) {
    throw new Error('Usage: pnpm release:prepare <patch|minor|major|beta|X.Y.Z[-beta.N]>');
  }
  if (run('git', ['status', '--porcelain']).trim() !== '') {
    throw new Error('The working tree has changes; commit or stash them first');
  }
  // Release tags exist only on GitHub, where publishing a release creates them.
  const fetched = spawnSync('git', ['fetch', '--quiet', '--tags', 'origin'], { cwd: root });
  if (fetched.status !== 0) throw new Error('Fetching the release tags from origin failed');

  const packageText = readFileSync(packageFile, 'utf8');
  const current = (JSON.parse(packageText) as { version: string }).version;
  const version = nextVersion(current, bump);
  writeFileSync(packageFile, packageText.replace(`"version": "${current}"`, `"version": "${version}"`));

  const section = run('pnpm', [
    '--dir',
    'tools',
    'exec',
    'git-cliff',
    '--config',
    '../cliff.toml',
    '--repository',
    '..',
    '--unreleased',
    '--tag',
    `v${version}`,
  ]).trim();
  const existing = existsSync(changelogFile) ? readFileSync(changelogFile, 'utf8') : changelogHeader;
  const firstSection = existing.search(/^## /m);
  const changelog =
    firstSection === -1
      ? `${existing.trimEnd()}\n\n${section}\n`
      : `${existing.slice(0, firstSection)}${section}\n\n${existing.slice(firstSection)}`;
  writeFileSync(changelogFile, changelog);
  run('pnpm', ['exec', 'prettier', '--write', 'CHANGELOG.md', 'app/package.json']);

  console.log(`Prepared v${version} (was ${current}).
Next steps:
  1. Curate the new section in CHANGELOG.md: user-facing wording, no internal details.
  2. Commit on a release branch: git commit -am "chore(release): v${version}"
  3. Push the branch; the release starts when the pull request is merged.`);
}

main(process.argv[2]);
